def solve(g):
    h,w=len(g),len(g[0])
    lines={i for i in range(h) if sum(1 for v in g[i] if v!=0)>2}
    gf=[]
    for i in lines:
        jj=0
        while jj<w:
            if g[i][jj]!=0:
                k=jj;v=g[i][jj]
                while jj+1<w and g[i][jj+1]==v: jj+=1
                kk=jj+1
                while kk<w and g[i][kk]==0: kk+=1
                # gap exists iff same color appears immediately after the zeros
                if kk<w and g[i][kk]==v:
                    for t in range(jj+1,kk): gf.append((i,t,v))
                jj=kk
            else: jj+=1
    free=[(r,c,g[r][c]) for c in range(w) for r in range(h)
          if g[r][c]!=0 and r not in lines]
    srcs=gf+free
    out=[row[:] for row in g]
    gfc={(a,b) for a,b,_ in gf}
    def walk(r,c,v,dr):
        rr=r+dr
        while 0<=rr<h and g[rr][c]==0 and (rr,c) not in gfc:
            out[rr][c]=v; rr+=dr
    for s in sorted(srcs,key=lambda s:s[0]):
        r,c,v=s
        out[r][c]=v
        walk(r,c,v,-1); walk(r,c,v,1)
    return out
